                            }
                            local = _il.DeclareLocal(localType);
                            WriteLocalSymbol(local, node);
                            _locals[declare] = local;

                            EnsureTop(localType);
                            PopType();
                            _il.Emit(OpCodes.Stloc, local);
                        }
                        else
