                    2 => typeof(ScriptFunctionDelegate2),
                    3 => typeof(ScriptFunctionDelegate3),
                    4 => typeof(ScriptFunctionDelegate4),
                    5 => typeof(ScriptFunctionDelegate5),
                    6 => typeof(ScriptFunctionDelegate6),
                    7 => typeof(ScriptFunctionDelegate7),
                    _ => typeof(ScriptFunctionDelegate)
                };
                _il.Emit(OpCodes.Newobj, delegateType.GetConstructors()[0]);
                return;
            }
            var oldIl = _il;
            var oldLastLocation = lastLocation;
            var oldScope = _scope;
            var oldLocals = new Dictionary<DeclareObject, LocalBuilder>(_locals);
            var oldUpvalueMap = new Dictionary<DeclareObject, int>(_upvalueMap);
            var oldLocalScopeCaptureIndex = new Dictionary<DeclareObject, LocalCaptureInfo>(_localScopeCaptureIndex);
            var oldScopeUpvaluesArray = _scopeUpvaluesArray;

            var funcName = node.Name?.Value;
            var fastArity = GetFastFunctionArity(node);
            var parameterTypes = fastArity >= 0 ? s_fastParameterTypes[fastArity] : s_spanParameterTypes;

            // Abstract ILGenerator retrieval
            (method, _il) = builder.DefineMethod(_currentModule.Name, funcName, typeof(ScriptDatum), parameterTypes);
            ilOffset = -1;
            lastLocation = long.MinValue;
            _currentModule.Methods[node] = method;
            if (IsDirectModuleFunction(node) && !_currentModule.DirectClosures.ContainsKey(node))
            {
                _currentModule.DirectClosures[node] = builder.DefineModuleField(_currentModule.Name, $"__direct_{node.Name.Value}", typeof(ClosureFunction));
            }
            _scope = _scope.Enter(ScopeType.Function);

            var oldConstantPool = new Dictionary<object, LocalBuilder>(_constantPool);
            _constantPool.Clear();

            if (node.Body != null)
            {
                var stats = _constantHoister.GetLiteralStats(node.Body);
                InitializeConstantPool(stats);
            }

            _locals.Clear();
            _upvalueMap.Clear();
            _localScopeCaptureIndex.Clear();
            _scopeUpvaluesArray = null;

            var oldStackState = _stackManager.GetState();
            _stackManager.Clear();

            // 1. Identify Upvalues needed from outer scope
            var analyzer = _closureAnalyzer;
            analyzer.Analyze(node, oldScope);

            foreach (var upvalueName in analyzer.Upvalues)
            {
                if (oldScope.Resolve(upvalueName, out var val) && val != null)
                {
                    // Inherit indexing from parent's context
                    if (oldUpvalueMap.TryGetValue(val, out int idx))
                    {
                        _upvalueMap[val] = idx;
                    }
                    else if (oldLocalScopeCaptureIndex.TryGetValue(val, out var locCapture))
                    {
                        _upvalueMap[val] = locCapture.Index;
                    }
                }
            }

            // 2. Pre-declare parameters
            for (int i = 0; i < node.Parameters.Count; i++)
            {
