            _scope = oldScope;
            _scopeUpvaluesArray = oldScopeUpvaluesArray;
            _locals.Clear();
            foreach (var kv in oldLocals) _locals.Add(kv.Key, kv.Value);
            _upvalueMap.Clear();
            foreach (var kv in oldUpvalueMap) _upvalueMap.Add(kv.Key, kv.Value);
