namespace AuroraScript.Compiler.Backend.Plans
{
    internal enum FunctionVisibility
    {
        Exported,
        ModuleVisible,
        InternalOnly
    }

    internal enum FunctionCallConvention
    {
        Span,
        Fast0,
        Fast1,
        Fast2,
        Fast3,
        Fast4,
