            Parameters = parameters ?? Array.Empty<string>();
            SourceName = sourceName;
        }

        public BlockStatement Body { get; }
        public IReadOnlyList<string> Parameters { get; }
        public string SourceName { get; }
        public FunctionPlan Function { get; set; }
    }
