using AuroraScript.Compiler.Emits;
using AuroraScript.Runtime;
using System;
using System.Reflection;
using System.Reflection.Emit;

namespace AuroraScript.Compiler.Backend.Emission
{
    internal sealed class ModuleInitializerEmitter
    {
        private readonly EmissionSession _session;
        private readonly ModulePlan _module;
        private MethodInfo _initializer;
        private ILGenerator _il;
        private bool _defined;
        private bool _emitted;

        public ModuleInitializerEmitter(EmissionSession session, ModulePlan module)
        {
            _session = session ?? throw new ArgumentNullException(nameof(session));
            _module = module ?? throw new ArgumentNullException(nameof(module));
        }

        public void Define()
        {
            if (_defined)
            {
                return;
            }

            var method = _session.Builder.DefineModuleInitMethod(_module.Declaration);
            _initializer = method.Method;
            _il = method.IL;
            _module.Initializer = _initializer;
            _defined = true;
        }

        public bool TryEmit(out MethodInfo initializer)
        {
            initializer = null;
            if (_emitted)
            {
                initializer = HasMaterializedFunctions(_module) ? _initializer : null;
                return initializer != null;
            }

            Define();
            var hasMaterializedFunctions = false;
            for (var i = 0; i < _module.Functions.Count; i++)
            {
                var function = _module.Functions[i];
                if (!CanMaterialize(function))
                {
                    continue;
                }

                hasMaterializedFunctions = true;
                EmitDefineFunction(_il, function);
            }

            _il.Emit(OpCodes.Ret);
            _emitted = true;
            if (!hasMaterializedFunctions)
            {
                return false;
            }

            initializer = _initializer;
            return true;
        }

        private static bool HasMaterializedFunctions(ModulePlan module)
        {
            for (var i = 0; i < module.Functions.Count; i++)
            {
                if (CanMaterialize(module.Functions[i]))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool CanMaterialize(FunctionPlan function)
        {
            return function.RequiresClosureObject &&
                function.Method != null &&
                function.UpvalueSlots.Length == 0 &&
                function.CapturedLocalSlots.Length == 0 &&
                !string.IsNullOrEmpty(function.Name);
        }

        private void EmitDefineFunction(ILGenerator il, FunctionPlan function)
        {
            il.Emit(OpCodes.Ldarg_0);
            il.Emit(OpCodes.Ldfld, RuntimeMetadata.CILContext_Module);
            _session.Builder.LoadStringConstant(il, function.Name);
            EmitClosure(il, function);
            il.Emit(OpCodes.Ldc_I4_1);
            il.Emit(OpCodes.Ldc_I4_1);
            il.Emit(OpCodes.Callvirt, RuntimeMetadata.ScriptObject_Define);
        }

        private void EmitClosure(ILGenerator il, FunctionPlan function)
        {
            il.Emit(OpCodes.Ldarg_0);
            il.Emit(OpCodes.Ldfld, RuntimeMetadata.CILContext_Domain);
            il.Emit(OpCodes.Ldarg_0);
            il.Emit(OpCodes.Ldfld, RuntimeMetadata.CILContext_Module);
            EmitDelegate(il, function);
            il.Emit(OpCodes.Call, RuntimeMetadata.Array_Empty_Upvalue);
            _session.Builder.LoadStringConstant(il, function.Name);
            il.Emit(OpCodes.Newobj, GetClosureConstructor(function.CallConvention));
        }

        private static void EmitDelegate(ILGenerator il, FunctionPlan function)
        {
            if (function.Method is DynamicMethod dynamicMethod)
            {
                var delegateId = RegisterDynamicDelegate(dynamicMethod, function.CallConvention);
                il.Emit(OpCodes.Dup);
                il.Emit(OpCodes.Ldc_I4, delegateId);
                il.Emit(OpCodes.Call, GetResolveDelegateMethod(function.CallConvention));
                return;
            }

            il.Emit(OpCodes.Ldnull);
            il.Emit(OpCodes.Ldftn, function.Method);
            il.Emit(OpCodes.Newobj, GetDelegateConstructor(function.CallConvention));
        }

        private static int RegisterDynamicDelegate(DynamicMethod dynamicMethod, FunctionCallConvention convention)
        {
            return convention switch
            {
                FunctionCallConvention.Fast0 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate0)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate0))),
                FunctionCallConvention.Fast1 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate1)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate1))),
                FunctionCallConvention.Fast2 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate2)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate2))),
                FunctionCallConvention.Fast3 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate3)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate3))),
                FunctionCallConvention.Fast4 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate4)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate4))),
                FunctionCallConvention.Fast5 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate5)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate5))),
                FunctionCallConvention.Fast6 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate6)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate6))),
                FunctionCallConvention.Fast7 => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate7)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate7))),
                _ => DynamicMethodRegistry.Register(dynamicMethod.Name, (ScriptFunctionDelegate)dynamicMethod.CreateDelegate(typeof(ScriptFunctionDelegate)))
            };
        }

        private static MethodInfo GetResolveDelegateMethod(FunctionCallConvention convention)
        {
            return convention switch
            {
                FunctionCallConvention.Fast0 => RuntimeMetadata.CILHelper_ResolveDelegate0,
                FunctionCallConvention.Fast1 => RuntimeMetadata.CILHelper_ResolveDelegate1,
                FunctionCallConvention.Fast2 => RuntimeMetadata.CILHelper_ResolveDelegate2,
                FunctionCallConvention.Fast3 => RuntimeMetadata.CILHelper_ResolveDelegate3,
                FunctionCallConvention.Fast4 => RuntimeMetadata.CILHelper_ResolveDelegate4,
                FunctionCallConvention.Fast5 => RuntimeMetadata.CILHelper_ResolveDelegate5,
                FunctionCallConvention.Fast6 => RuntimeMetadata.CILHelper_ResolveDelegate6,
                FunctionCallConvention.Fast7 => RuntimeMetadata.CILHelper_ResolveDelegate7,
                _ => RuntimeMetadata.CILHelper_ResolveDelegate
            };
        }

        private static ConstructorInfo GetDelegateConstructor(FunctionCallConvention convention)
        {
            return GetDelegateType(convention).GetConstructors()[0];
        }

        private static Type GetDelegateType(FunctionCallConvention convention)
        {
            return convention switch
            {
                FunctionCallConvention.Fast0 => typeof(ScriptFunctionDelegate0),
                FunctionCallConvention.Fast1 => typeof(ScriptFunctionDelegate1),
                FunctionCallConvention.Fast2 => typeof(ScriptFunctionDelegate2),
                FunctionCallConvention.Fast3 => typeof(ScriptFunctionDelegate3),
                FunctionCallConvention.Fast4 => typeof(ScriptFunctionDelegate4),
                FunctionCallConvention.Fast5 => typeof(ScriptFunctionDelegate5),
                FunctionCallConvention.Fast6 => typeof(ScriptFunctionDelegate6),
                FunctionCallConvention.Fast7 => typeof(ScriptFunctionDelegate7),
                _ => typeof(ScriptFunctionDelegate)
            };
        }

        private static ConstructorInfo GetClosureConstructor(FunctionCallConvention convention)
        {
            return convention switch
            {
                FunctionCallConvention.Fast0 => RuntimeMetadata.ClosureFunction_Ctor0,
                FunctionCallConvention.Fast1 => RuntimeMetadata.ClosureFunction_Ctor1,
                FunctionCallConvention.Fast2 => RuntimeMetadata.ClosureFunction_Ctor2,
