                FunctionCallConvention.Fast6 => RuntimeMetadata.ClosureFunction_Ctor6,
                FunctionCallConvention.Fast7 => RuntimeMetadata.ClosureFunction_Ctor7,
                _ => RuntimeMetadata.ClosureFunction_Ctor
